<?php
/** TEMP PS S1625 run e16d — deploy petshop-dev-pastas.php v1.1 → v1.2 (leidimų sąrašas), opcija `ps_dev_pastas_leisti`=terra@petshop.lt, Venipak siuntėjo asmuo (sendercontactperson) → „UAB Avesa“ (Raimis: „ištrink mano vardą“); md5 sargai, kopija, ping → rollback. */
add_action('init', function(){
  if (!isset($_GET['ps_e16d'])) return;
  $o=array('v'=>'S1625 e16d'); global $wpdb; $p=$wpdb->prefix; set_time_limit(200);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  $ping=function(){ $r=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat'),array('timeout'=>90,'sslverify'=>false)); $b=(string)wp_remote_retrieve_body($r); return array('code'=>wp_remote_retrieve_response_code($r),'fatal'=>(int)(stripos($b,'Fatal error')!==false||stripos($b,'Parse error')!==false),'err'=>is_wp_error($r)?$r->get_error_message():''); };
  $F=array(
    array('f'=>'petshop-dev-pastas.php','buvo'=>'ed7e80a87be1994244a565385fe46af0','md5'=>'f761afc71f5e42f5205366076d79d16f','bk'=>'petshop-dev-pastas-v11-BACKUP-','b64'=>''));
  $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk); $done=array();
  try{
  foreach($F as $x){ $c=base64_decode($x['b64'],true); if($c===false||md5($c)!==$x['md5']){ $o['STOP']=$x['f'].' b64/md5'; break; }
    try { token_get_all($c, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']=$x['f'].' token: '.$e->getMessage(); break; }
    $t=WPMU_PLUGIN_DIR.'/'.$x['f']; $b=md5_file($t); if($b!==$x['buvo']){ $o['STOP']=$x['f'].' gyvas nežinomas '.$b; break; }
    $bkf=$bk.'/'.$x['bk'].date('Y-m-d').'.php'; copy($t,$bkf); $o[$x['f']]=array('backup'=>basename($bkf),'rasyta'=>file_put_contents($t,$c),'po'=>md5_file($t)); if(function_exists('opcache_invalidate')){ @opcache_invalidate($t,true); } $done[]=array($t,$bkf);
    $o[$x['f']]['ping']=$ping(); if($o[$x['f']]['ping']['fatal']||$o[$x['f']]['ping']['code']>=500||$o[$x['f']]['ping']['err']){ foreach($done as $dd){ copy($dd[1],$dd[0]); } $o['ATKURTA']='visi atkurti'; break; } }
  if(empty($o['STOP'])&&empty($o['ATKURTA'])){ update_option('ps_dev_pastas_leisti','terra@petshop.lt',false); $o['leisti']=get_option('ps_dev_pastas_leisti');
    $s=get_option('shopup_venipak_shipping_settings'); $o['siuntejas_buvo']=is_array($s)?array('person'=>$s['shopup_venipak_shipping_field_sendercontactperson']??null,'name'=>$s['shopup_venipak_shipping_field_sendername']??null,'tel'=>$s['shopup_venipak_shipping_field_sendercontacttel']??null,'email'=>$s['shopup_venipak_shipping_field_sendercontactemail']??null):'?';
    if(is_array($s)){ update_option('ps_s1625_vp_sender_buvo',$s['shopup_venipak_shipping_field_sendercontactperson']??'',false); $s['shopup_venipak_shipping_field_sendercontactperson']='UAB Avesa'; update_option('shopup_venipak_shipping_settings',$s); $s2=get_option('shopup_venipak_shipping_settings'); $o['siuntejas_po']=$s2['shopup_venipak_shipping_field_sendercontactperson']??null; } }
  $o['versijos']=array('devpastas'=>md5_file(WPMU_PLUGIN_DIR.'/petshop-dev-pastas.php'));
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.basename($e->getFile()).':'.$e->getLine(); }
  $J($o);
},99);
